import exampleAnswers from './example-answers.json'
import type { Citation } from './types'

// Finished, high-confidence answers for the homepage examples, generated by
// the live pipeline (npm run answers:precompute) so an example click costs no
// model call. Exact question match only: a similar-but-different question
// must never receive another question's answer.
export interface CachedAnswer {
  answer: string
  citations: Citation[]
}

type AnswerCache = Record<string, CachedAnswer>

export function getCachedAnswer(question: string, cache: AnswerCache = exampleAnswers as AnswerCache): CachedAnswer | null {
  // Set while regenerating, so the pipeline answers instead of the cache.
  if (process.env.ANSWER_CACHE_DISABLED === '1') return null
  if (!Object.hasOwn(cache, question)) return null
  const entry = cache[question]
  if (!entry || typeof entry.answer !== 'string' || !entry.answer.trim() || !Array.isArray(entry.citations)) return null
  if (entry.citations.length === 0 || entry.citations.some((c) => !c.timestampVerified)) return null
  return entry
}
